    "uuid": "^9.0.0"
  }
}

export type SegmentEventType =
  | 'track'
  | 'page'
  | 'screen'

export type JSONPrimitive = string | number | boolean | null
export type JSONValue = JSONPrimitive | JSONObject | JSONArray
export type JSONObject = { [member: string]: JSONValue }
export type JSONArray = JSONValue[]

export type EventProperties = Record<string, any>

export type Integrations = {
  All?: boolean
  [integration: string]: boolean | JSONObject | undefined
}

export interface CoreOptions {
  integrations?: Integrations
  timestamp?: Timestamp
  context?: CoreExtraContext
  anonymousId?: string
  userId?: string
  // ugh, this is ugly, but we allow literally any property to be passed to options (which get spread onto the event)
  [key: string]: any
}

/**
 * Context is a dictionary of extra information that provides useful context about a datapoint, for example the user’s ip address or locale. You should only use Context fields for their intended meaning.
 * @link https://segment.com/docs/connections/spec/common/#context
 */
export interface CoreExtraContext {
  /**
   * This is usually used to flag an .identify() call to just update the trait, rather than "last seen".
   */
  active?: boolean

  /**
   * Current user's IP address.
   */
  ip?: string

  /**
   * Locale string for the current user, for example en-US.
   * @example en-US
   */
  locale?: string
  /**
   * Dictionary of information about the user’s current location.
   */
  location?: {
    /**
     * @example San Francisco
     */
    city?: string
    /**
     * @example United States
     */
    country?: string
    /**
     * @example 40.2964197
     */
    latitude?: string
    /**
     * @example -76.9411617
     */
    longitude?: string
    /**
     * @example CA
     */
    region?: string
    /**
     * @example 100
     */
    speed?: number
  }

  /**
   * Dictionary of information about the current web page.
   */
  page?: {
    /**
     * @example /academy/
     */
    path?: string
    /**
     * @example https://www.foo.com/
     */
    referrer?: string
    /**
     * @example projectId=123
     */
    search?: string
    /**
     * @example Analytics Academy
     */
    title?: string
    /**
     * @example https://segment.com/academy/
     */
    url?: string
  }

  /**
   * User agent of the device making the request.
   */
  userAgent?: string

  /**
   * Information about the current library.
   *
   * **Automatically filled out by the library.**
   *
   * This type should probably be "never"
   */
  library?: {
    /**
     * @example analytics-node-next/latest
     */
    name: string
    /**
     * @example  "1.43.1"
     */
    version: string
  }

  /**
   * Dictionary of information about the campaign that resulted in the API call, containing name, source, medium, term, content, and any other custom UTM parameter.
   */
  campaign?: {
    name: string
    term: string
    source: string
    medium: string
    content: string
  }

  /**
   * Dictionary of information about the way the user was referred to the website or app.
   */
  referrer?: {
    type?: string
    name?: string
    url?: string
    link?: string

    id?: string // undocumented
    btid?: string // undocumented?
    urid?: string // undocumented?
  }

  amp?: {
    // undocumented?
    id: string
  }

  [key: string]: any
}

type ID = string | null | undefined

export interface CoreSegmentEvent {
  messageId?: string
  type: SegmentEventType

  // page specific
  category?: string
  name?: string

  properties?: EventProperties

  integrations?: Integrations
  context?: CoreExtraContext
  options?: CoreOptions

  userId?: ID
  anonymousId?: ID
  // TODO: consider re-adding these later
  // groupId?: ID
  // previousId?: ID

  event?: string

  writeKey?: string

  sentAt?: Date

  _metadata?: SegmentEventMetadata

  timestamp?: Timestamp
}

export interface SegmentEventMetadata {
  failedInitializations?: unknown[]
  bundled?: string[]
  unbundled?: string[]
  nodeVersion?: string
  bundledConfigIds?: string[]
  unbundledConfigIds?: string[]
  bundledIds?: string[]
}

export type Timestamp = Date | string

/**
 * A Plan allows users to specify events and which destinations they would like them to be sent to
 */
export interface Plan {
  track?: TrackPlan
  identify?: TrackPlan
  group?: TrackPlan
}

export interface TrackPlan {
  [key: string]: PlanEvent | undefined
  // __default SHOULD always exist, but marking as optional for extra safety.
  __default?: PlanEvent
}

export interface PlanEvent {
  /**
   * Whether or not this plan event is enabled
   */
  enabled: boolean
  /**
   * Which integrations the plan event applies to
   */
  integrations?: {
    [key: string]: boolean
  }
}

import { createContext } from "./context/createContext";
import { CoreSegmentEvent, SegmentEventType } from "interfaces";
import { v4 as uuidv4 } from "uuid";

const BACKEND_URL = "app.stably.dev";

interface ExtraOptions {
  cdnUrl?: string;
  userId?: string;
}

export class Analytics {
  readonly anonymousId = uuidv4();
  readonly cdnUrl: string;

  constructor(
    private readonly writeKey: string,
    private readonly options?: ExtraOptions
  ) {
    this.cdnUrl = this.options?.cdnUrl ?? BACKEND_URL;
  }

  public track = (eventName: string, properties?: Record<string, any>) =>
    this.emitEvent(eventName, "track", properties);

  private async emitEvent(
    eventName: string,
    type: SegmentEventType,
    properties?: Record<string, any>
  ): Promise<void> {
    const now = new Date();

    const request: CoreSegmentEvent = {
      event: eventName,
      type: type,
      anonymousId: this.anonymousId,
      userId: this.options?.userId,
      properties: properties,
      writeKey: this.writeKey,
      timestamp: now,
      sentAt: now,
      context: createContext(),
    };

    await fetch(`http://${this.cdnUrl}/api/public/track/v1`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(request),
    });
  }
}

import { CoreExtraContext } from "interfaces";
import { version } from "../gen/version";

// normalize and dispatch
export function createContext(): CoreExtraContext {
  return {
    // @ts-ignore
    locale: navigator.userLanguage || navigator.language,
    page: pageDefaults(),
    userAgent: window.navigator.userAgent,
    library: {
      name: "stably",
      version,
    },
    campaign: utm(window.location.search),
    // TODO: skipping referrer information for now
    referrer: {},
  };
}

function utm(query: string): {
  name: string;
  term: string;
  source: string;
  medium: string;
  content: string;
} {
  if (query.startsWith("?")) {
    query = query.substring(1);
  }
  query = query.replace(/\?/g, "&");

  const res = query.split("&").reduce((acc, str) => {
    const [k, v = ""] = str.split("=");
    if (k.includes("utm_") && k.length > 4) {
      let utmParam = k.substr(4);
      if (utmParam === "campaign") {
        utmParam = "name";
      }
      acc[utmParam] = gracefulDecodeURIComponent(v);
    }
    return acc;
  }, {} as Record<string, string>);

  return {
    name: res["name"],
    term: res["term"],
    source: res["source"],
    medium: res["medium"],
    content: res["content"],
  };
}

/**
 * Tries to gets the unencoded version of an encoded component of a
 * Uniform Resource Identifier (URI). If input string is malformed,
 * returns it back as-is.
 *
 * Note: All occurences of the `+` character become ` ` (spaces).
 **/
function gracefulDecodeURIComponent(encodedURIComponent: string): string {
  try {
    return decodeURIComponent(encodedURIComponent.replace(/\+/g, " "));
  } catch {
    return encodedURIComponent;
  }
}

interface PageDefault {
  [key: string]: unknown;
  path: string;
  referrer: string;
  search: string;
  title: string;
  url: string;
}

/**
 * Get the current page's canonical URL.
 *
 * @return {string|undefined}
 */
function canonical(): string {
  const tags = document.getElementsByTagName("link");
  let canon: string | null = "";

  Array.prototype.slice.call(tags).forEach((tag) => {
    if (tag.getAttribute("rel") === "canonical") {
      canon = tag.getAttribute("href");
    }
  });

  return canon;
}

/**
 * Return the canonical path for the page.
 */
function canonicalPath(): string {
  const canon = canonical();
  if (!canon) {
    return window.location.pathname;
  }

  const a = document.createElement("a");
  a.href = canon;
  const pathname = !a.pathname.startsWith("/") ? "/" + a.pathname : a.pathname;

  return pathname;
}

/**
 * Return the canonical URL for the page concat the given `search`
 * and strip the hash.
 */

export function canonicalUrl(search = ""): string {
  const canon = canonical();
  if (canon) {
    return canon.includes("?") ? canon : `${canon}${search}`;
  }
  const url = window.location.href;
  const i = url.indexOf("#");
  return i === -1 ? url : url.slice(0, i);
}

/**
 * Return a default `options.context.page` object.
 *
 * https://segment.com/docs/spec/page/#properties
 */
export function pageDefaults(): PageDefault {
  return {
    path: canonicalPath(),
    referrer: document.referrer,
    search: location.search,
    title: document.title,
    url: canonicalUrl(location.search),
  };
}
